import { Inject, Injectable, PLATFORM_ID, TransferState, makeStateKey } from '@angular/core';
import { isPlatformBrowser, isPlatformServer } from '@angular/common';
import { catchError, tap } from 'rxjs/operators';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable, throwError, of } from 'rxjs';

import { environment } from '../../../environments/environment';

@Injectable({
	providedIn: 'root'
})
export class ProjectService {

	constructor(
		private http: HttpClient,
		private transferState: TransferState,
		@Inject(PLATFORM_ID) private platformId: Object,
	) { }

	// TransferState so the client reuses the server's already-fetched response
	// instead of re-fetching after hydration. Without this, the client's first
	// render briefly sees empty data while the server's render was already
	// populated — a mismatch that can make Angular discard the server-rendered
	// markup for anything conditioned on this data (e.g. recent-work-marquee).
	getAllProjects = (data: any): Observable<any> => {
		const endpoint = environment.baseUrl + '/api/project/listprojects';
		const stateKey = makeStateKey<any>(`all-projects:${JSON.stringify(data)}`);

		if (isPlatformBrowser(this.platformId) && this.transferState.hasKey(stateKey)) {
			const cached = this.transferState.get(stateKey, null);
			this.transferState.remove(stateKey);
			return of(cached);
		}

		return this.http.post(endpoint, data).pipe(
			tap((response) => {
				if (isPlatformServer(this.platformId)) {
					this.transferState.set(stateKey, response);
				}
			}),
			catchError((err) => {
				return of({ code: 200, status: 'Success', result: [] }); // ✅ use 'result' not 'data'
			})
		);
	};


	sendContactForm(data: any): Observable<any> {
		return this.http.post(`${environment.baseUrl}/api/project/referralmail`, data);
	}

}
